\documentclass{article}
\usepackage[paperwidth=594mm,paperheight=841mm,margin=0mm]{geometry}
\usepackage{tcolorbox}
\tcbuselibrary{poster,skins,fitting}
\usepackage{graphicx}
\usepackage{amsmath,amssymb}
\usepackage{enumitem}
\usepackage[table]{xcolor}
\usepackage{lmodern}
\usepackage[T1]{fontenc}
\pagestyle{empty}

% ── Color Palette ──
\definecolor{primary}{HTML}{0077B6}
\definecolor{secondary}{HTML}{0096C7}
\definecolor{accent}{HTML}{FFB703}
\definecolor{bgposter}{HTML}{F0F8FF}
\definecolor{bluebg}{HTML}{E4F4FF}
\definecolor{amberbg}{HTML}{FFF8E6}
\definecolor{tealbg}{HTML}{E6F7F7}
\definecolor{greenbg}{HTML}{E8F5E9}
\definecolor{blueheader}{HTML}{D0E8F8}
\definecolor{amberheader}{HTML}{FFE9B3}
\definecolor{tealheader}{HTML}{CCE8E8}
\definecolor{greenheader}{HTML}{D4EDDA}
\definecolor{textdark}{HTML}{1F2937}
\definecolor{textgray}{HTML}{4B5563}
\definecolor{stathighlight}{HTML}{FFF3CD}

\pagecolor{bgposter}
\color{textdark}

% ── List styling ──
\setlist[itemize]{leftmargin=20pt, itemsep=4pt, parsep=2pt, topsep=2pt,
  label={\color{secondary}\textbullet}}
\setlist[enumerate]{leftmargin=20pt, itemsep=4pt, parsep=2pt, topsep=2pt,
  label={\color{primary}\bfseries\arabic*.}}

% ── Figure+caption macro ──
\newcommand{\posterfig}[3]{%
  \centering\includegraphics[width=#1\linewidth]{#2}\\[3mm]
  {\fontsize{24}{30}\selectfont\color{textgray}\textit{#3}}\vspace{2mm}%
}

% ── Card styles (left accent stripe design) ──
\tcbset{
  phasecard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=white,
    borderline west={6pt}{0pt}{secondary},
    left=14pt, right=12pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{36}{44}\selectfont\bfseries\color{primary},
    coltitle=primary, colbacktitle=blueheader,
    toptitle=5pt, bottomtitle=5pt,
    titlerule=2pt, titlerule style={secondary!60},
    valign=top, drop shadow={opacity=0.15},
  },
  phase2card/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=white,
    borderline west={6pt}{0pt}{accent},
    left=14pt, right=12pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{36}{44}\selectfont\bfseries\color{accent!80!textdark},
    coltitle=accent!80!textdark, colbacktitle=amberheader,
    toptitle=5pt, bottomtitle=5pt,
    titlerule=2pt, titlerule style={accent!60},
    valign=top, drop shadow={opacity=0.15},
  },
  phase3card/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=white,
    borderline west={6pt}{0pt}{0077B6},
    left=14pt, right=12pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{36}{44}\selectfont\bfseries\color{primary},
    coltitle=primary, colbacktitle=tealheader,
    toptitle=5pt, bottomtitle=5pt,
    titlerule=2pt, titlerule style={primary!60},
    valign=top, drop shadow={opacity=0.15},
  },
  phase4card/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=white,
    borderline west={6pt}{0pt}{2E7D32},
    left=14pt, right=12pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{36}{44}\selectfont\bfseries\color{2E7D32},
    coltitle=2E7D32, colbacktitle=greenheader,
    toptitle=5pt, bottomtitle=5pt,
    titlerule=2pt, titlerule style={2E7D32!60},
    valign=top, drop shadow={opacity=0.15},
  },
}

\begin{document}
\begin{tcbposter}[
  coverage={spread},
  poster={columns=2, rows=20, spacing=0mm},
]

% ══ TITLE BAR ══
\posterbox[
  enhanced, colback=primary, colframe=primary, colupper=white,
  arc=0pt, boxrule=0pt,
  left=30pt, right=30pt, top=10pt, bottom=8pt,
  halign=center, valign=center,
  drop shadow={opacity=0.35}
]{name=title, column=1, span=2, between=top and row4}{
  {\fontsize{72}{86}\selectfont\bfseries COVID-19 Emergency Response}\\[10pt]
  {\fontsize{38}{46}\selectfont\bfseries From Detection to Recovery}\\[8pt]
  {\fontsize{28}{34}\selectfont\color{white!80} WHO-Guided Process Flow | 194 Member States Coordinated}
}

% ══ STATS BANNER ══
\posterbox[
  enhanced, colback=primary!12!white, boxrule=0pt, arc=0pt,
  left=10pt, right=10pt, top=4pt, bottom=4pt,
  valign=center, borderline south={3pt}{0pt}{primary!40},
]{name=stats, column=1, span=2, between=row4 and row6}{
  \centering
  \begin{minipage}[c]{0.28\linewidth}\centering
    \fcolorbox{primary!50}{stathighlight}{\parbox{0.9\linewidth}{%
      \centering\vspace{5pt}%
      {\fontsize{60}{72}\selectfont\bfseries\color{primary} 194}\\[3pt]
      {\fontsize{24}{30}\selectfont\color{textdark} WHO Member States}\\[2pt]
      {\fontsize{22}{28}\selectfont\color{textgray} Coordinated}\vspace{4pt}%
    }}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.36\linewidth}\centering
    \fcolorbox{accent!60}{stathighlight}{\parbox{0.9\linewidth}{%
      \centering\vspace{5pt}%
      {\fontsize{60}{72}\selectfont\bfseries\color{accent!85!textdark} 1.9B}\\[3pt]
      {\fontsize{24}{30}\selectfont\color{textdark} COVAX Vaccine Doses}\\[2pt]
      {\fontsize{22}{28}\selectfont\color{textgray} Delivered by mid-2023}\vspace{4pt}%
    }}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.28\linewidth}\centering
    \fcolorbox{secondary!50}{stathighlight}{\parbox{0.9\linewidth}{%
      \centering\vspace{5pt}%
      {\fontsize{60}{72}\selectfont\bfseries\color{secondary} 200+}\\[3pt]
      {\fontsize{24}{30}\selectfont\color{textdark} Technical Guidance}\\[2pt]
      {\fontsize{22}{28}\selectfont\color{textgray} Documents Issued}\vspace{4pt}%
    }}
  \end{minipage}
}

% ══ PHASE 1: SURVEILLANCE & EARLY DETECTION ══
\posterbox[
  phasecard,
  title={Phase 1: Surveillance \& Early Detection}
]{name=phase1, column=1, between=row6 and row9}{
  \fontsize{32}{40}\selectfont
  \begin{itemize}[itemsep=8pt]
    \item National labs report unusual respiratory illness clusters to WHO
    \item IHR framework enables rapid information sharing across borders
    \item First Disease Outbreak News published 5 January 2020
  \end{itemize}
  \vspace{4pt}
  \colorbox{primary!18}{\parbox{0.92\linewidth}{%
    \fontsize{26}{32}\selectfont\color{primary}
    \textbf{6 WHO Regions:} Africa, Americas, South-East Asia, Europe, Eastern Mediterranean, Western Pacific
  }}
}

% ══ PHASE 2: RISK ASSESSMENT & ALERT ══
\posterbox[
  phase2card,
  title={Phase 2: Risk Assessment \& Alert}
]{name=phase2, column=2, between=row6 and row9}{
  \fontsize{32}{40}\selectfont
  \begin{itemize}[itemsep=8pt]
    \item Rapid risk assessment evaluates spread, severity, and health system capacity
    \item Regular situation reports keep global community informed
    \item PHEIC declared on \textbf{30 January 2020}
  \end{itemize}
  \vspace{4pt}
  \colorbox{accent!25}{\parbox{0.92\linewidth}{%
    \fontsize{26}{32}\selectfont\color{textdark}
    \textbf{Outcome:} Public Health Emergency of International Concern (PHEIC) — highest WHO alert level
  }}
}

% ══ PHASE 3: RESPONSE OPERATIONS & CLINICAL MANAGEMENT ══
\posterbox[
  phase3card,
  title={Phase 3: Response Operations \& Clinical Management}
]{name=phase3, column=1, between=row9 and row14}{
  \fontsize{30}{38}\selectfont
  \begin{itemize}[itemsep=6pt]
    \item \textbf{Infection Prevention:} PPE guidance, hand hygiene, facility decontamination
    \item \textbf{Clinical Care:} Treatment protocols, oxygen therapy, ICU guidelines
    \item \textbf{Health Workforce:} Training, surge staffing, mental health support
    \item \textbf{Supply Chain:} Essential medicines, diagnostics, equipment procurement
    \item \textbf{Research:} Solidarity Trial, vaccine R\&D coordination
  \end{itemize}
  \vspace{6pt}
  \colorbox{primary!15}{\parbox{0.92\linewidth}{%
    \fontsize{26}{32}\selectfont\color{textdark}
    Partners: UNICEF, World Bank, Médecins Sans Frontières
  }}
}

% ══ PHASE 4: PUBLIC HEALTH & SOCIAL MEASURES ══
\posterbox[
  phase4card,
  title={Phase 4: Public Health \& Social Measures}
]{name=phase4, column=2, between=row9 and row14}{
  \fontsize{30}{38}\selectfont
  \begin{itemize}[itemsep=8pt]
    \item \textbf{Testing \& Contact Tracing:} PCR and rapid antigen testing at scale
    \item \textbf{Quarantine \& Isolation:} Evidence-based guidelines updated as variants emerged
    \item \textbf{Vaccination:} COVAX delivered 1.9B doses to 146 countries
  \end{itemize}
  \vspace{4pt}
  \colorbox{2E7D32!20}{\parbox{0.92\linewidth}{%
    \fontsize{26}{32}\selectfont\color{2E7D32}
    \textbf{Risk Communication:} Multilingual campaigns combating misinformation across social and traditional media
  }}
}

% ══ PHASE 5: RECOVERY & HEALTH SYSTEM RESILIENCE ══
\posterbox[
  phasecard,
  title={Phase 5: Recovery \& Health System Resilience}
]{name=phase5, column=1, between=row14 and row18}{
  \fontsize{30}{38}\selectfont
  \begin{itemize}[itemsep=8pt]
    \item Restoring routine health services disrupted during pandemic
    \item Strengthening preparedness with updated national action plans
    \item Addressing long COVID and mental health impacts
    \item Conducting after-action reviews to capture lessons learned
  \end{itemize}
  \vspace{4pt}
  \colorbox{primary!18}{\parbox{0.92\linewidth}{%
    \fontsize{26}{32}\selectfont\color{primary}
    \textbf{COVID-19 Dashboard:} Millions of data points tracked daily for real-time situational awareness
  }}
}

% ══ GLOBAL COORDINATION CALLOUT ══
\posterbox[
  enhanced, colback=accent!15, boxrule=0pt, arc=0pt,
  left=14pt, right=14pt, top=8pt, bottom=8pt,
  valign=center, halign=center,
  borderline={3pt}{0pt}{accent}
]{name=global, column=2, between=row14 and row18}{
  {\fontsize{36}{44}\selectfont\bfseries\color{accent!80!textdark} Global Health Architecture}\\[8pt]
  {\fontsize{28}{36}\selectfont\color{textdark}
    \begin{itemize}[itemsep=6pt, label={\color{accent}\textbullet}]
      \item Coordinated through WHO's Health Emergencies Programme
      \item Structured process across all 6 WHO regions
      \item Designed to save lives and build pandemic resilience
    \end{itemize}
  }
}

% ══ PROCESS FLOW FOOTER ══
\posterbox[
  enhanced, colback=primary, colframe=primary, colupper=white,
  arc=0pt, boxrule=0pt,
  left=20pt, right=20pt, top=6pt, bottom=6pt,
  halign=center, valign=center,
  drop shadow={opacity=0.25}
]{name=footer, column=1, span=2, between=row18 and bottom}{
  \fontsize{30}{36}\selectfont
  \colorbox{white!20}{\parbox{0.25\linewidth}{\centering\bfseries\color{white} Surveillance}%
  \hfill$\rightarrow$\hfill%
  \colorbox{white!20}{\parbox{0.25\linewidth}{\centering\bfseries\color{white} Risk Assessment}%
  \hfill$\rightarrow$\hfill%
  \colorbox{white!20}{\parbox{0.25\linewidth}{\centering\bfseries\color{white} Response}%
  \hfill$\rightarrow$\hfill%
  \colorbox{white!20}{\parbox{0.25\linewidth}{\centering\bfseries\color{white} Recovery}
}

\end{tcbposter}
\end{document}

