  \centering
  \begin{minipage}[c]{0.28\linewidth}\centering
    \fcolorbox{primary!50}{stathighlight}{\parbox{0.9\linewidth}{%
      \centering\vspace{5pt}%
      {\fontsize{60}{72}\selectfont\bfseries\color{primary} 194}\\[3pt]
      {\fontsize{24}{30}\selectfont\color{textdark} WHO Member States}\\[2pt]
      {\fontsize{22}{28}\selectfont\color{textgray} Coordinated}\vspace{4pt}%
    }}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.36\linewidth}\centering
    \fcolorbox{accent!60}{stathighlight}{\parbox{0.9\linewidth}{%
      \centering\vspace{5pt}%
      {\fontsize{60}{72}\selectfont\bfseries\color{accent!85!textdark} 1.9B}\\[3pt]
      {\fontsize{24}{30}\selectfont\color{textdark} COVAX Vaccine Doses}\\[2pt]
      {\fontsize{22}{28}\selectfont\color{textgray} Delivered by mid-2023}\vspace{4pt}%
    }}
  \end{minipage}\hfill
